impl State {
    /// A normal run: drops everything invented (the list, the open session, the picker lists). `discover` is
    /// whether a Fleet is still to be looked for. Scenes, headless runs and `--demo` never call this.
    pub fn go_live(&mut self, discover: bool) {
        self.projects.clear();
        self.route = fleet::store::Route::None;
        self.pickers = fleet::catalog::Pickers::new(false);
        self.searching = discover;
        self.live = true;
    }

    /// Showing the invented data: a scene, a headless run or `--demo`. A normal run never does, with a Fleet or without.
    pub fn is_mock(&self) -> bool {
        self.link.is_none() && !self.live
    }

    /// Discovery found no Fleet: say so, and leave the window empty.
    pub fn on_no_fleet(&mut self, notice: String) {
        self.searching = false;
        self.no_fleet = true;
        self.notice = Some(notice);
    }

    pub fn project(&self) -> &Project {
        self.projects.get(self.open_at().0).filter(|p| self.open_at().1 < p.sessions.len()).unwrap_or(&self.blank)
    }

    pub fn session(&self) -> &Session {
        let at = self.open_at();
        if at.0 == fleet::store::ELSEWHERE {
            return self.store.elsewhere_at(at.1).unwrap_or(&self.blank.sessions[0]);
        }
        self.project().sessions.get(at.1).unwrap_or(&self.blank.sessions[0])
    }

    /// Where the open session is in the list now: (project, session), `(ELSEWHERE, n)` for the n-th session kept from
    /// another machine, or `(usize::MAX, 0)` when none is open or it isn't anywhere. Derived from the route each time, never kept.
    pub fn open_at(&self) -> (usize, usize) {
        let fleet::store::Route::Session(id) = &self.route else { return (usize::MAX, 0) };
        self.projects
            .iter()
            .enumerate()
            .find_map(|(p, project)| project.sessions.iter().position(|s| &s.id == id).map(|i| (p, i)))
            .or_else(|| self.store.elsewhere_index(id).map(|i| (fleet::store::ELSEWHERE, i)))
            .unwrap_or((usize::MAX, 0))
    }

    /// Gives the session at (project, session) another id (a scene or a test standing in for a server's session); the
    /// route follows when it was the open one.
    pub fn set_session_id(&mut self, at: (usize, usize), id: &str) {
        let was_open = self.open_at() == at;
        self.projects[at.0].sessions[at.1].id = id.into();
        if was_open {
            self.route = fleet::store::Route::Session(id.into());
        }
    }

    /// Makes the session at (project, session) the open one; a place with no session leaves none open.
    pub fn set_open(&mut self, at: (usize, usize)) {
        let route = match self.projects.get(at.0).and_then(|p| p.sessions.get(at.1)) {
            Some(s) => fleet::store::Route::Session(s.id.clone()),
            None => fleet::store::Route::None,
        };
        self.go(route);
    }

    /// A scene of the status bar: the open session's status (`None`: no session, the window a server that has none draws).
    pub fn show_status_hints(&mut self, dark: bool, status: Option<mock::Status>) {
        self.dark = Some(dark);
        match status {
            Some(status) => {
                let (p, i) = self.open_at();
                self.projects[p].sessions[i].status = status;
            }
            None => self.go_live(false),
        }
    }

    /// Every session in list order, for the previous/next keys.
    fn order(&self) -> Vec<(usize, usize)> {
        self.projects.iter().enumerate().flat_map(|(p, project)| (0..project.sessions.len()).map(move |s| (p, s))).collect()
    }

    /// Whether a real or mock session is open (not the blank stand-in).
    pub fn has_session(&self) -> bool {
        self.open_at().0 != usize::MAX
    }

    pub fn step_session(&mut self, by: isize, tx: &mut Tx) {
        self.step(by, tx);
    }

    /// Shows Fleet's toast for `seconds`, with an optional pill action.
    pub fn toast(&mut self, message: String, action: Option<String>, seconds: f64, tx: &mut Tx) {
        self.ui.toast = Some(ui::toast::Toast { kind: Default::default(), message, action, until: self.clock + seconds, total: seconds });
        tx.wake_after(std::time::Duration::from_millis(100));
    }

    fn step(&mut self, by: isize, tx: &mut Tx) {
        let order = self.order();
        if order.is_empty() {
            return;
        }
        let at = order.iter().position(|&id| id == self.open_at()).unwrap_or(0) as isize;
        let (p, i) = order[(at + by).rem_euclid(order.len() as isize) as usize];
        self.open_session(p, i, tx);
    }
}

impl State {
    /// The session the composer's text belongs to: the open session's id, or a stand-in for the mock data's
    /// sessions, which have none. `None` while a server's list hasn't arrived, so text typed then waits for it.
    pub(crate) fn draft_owner(&self) -> Option<String> {
        match (&self.route, self.open_id()) {
            (_, Some(id)) => Some(id),
            (fleet::store::Route::Session(id), None) if self.is_mock() && !id.is_empty() => Some(id.clone()),
            _ => None,
        }
    }

    /// What the composer sees of the open session (`composerStatus`): busy while a turn runs or right after a send.
    pub fn composer_status(&self) -> composer::status::ComposerStatus {
        use composer::status::{ComposerStatus, composer_status};
        let activity = match self.session().status {
            Status::Working => "busy",
            Status::NeedsInput => "waiting_input",
            Status::Idle => "idle",
        };
        let status = composer_status(Some(activity), self.optimistic.is_some());
        // A question or permission the session waits on is not a turn the optimistic guess can hide.
        if activity == "waiting_input" { ComposerStatus::WaitingInput } else { status }
    }

    /// Whether the composer takes input at all (`isDisabled`, row 1.9). A session list row without `capabilities` is
    /// taken as able: its `lifecycleStatus` isn't on the row yet, and "running" is what the rule would ask of it.
    pub fn composer_disabled(&self) -> bool {
        let row = &self.session().row;
        let gate = composer::status::SessionGate { archived: row.archived, can_prompt: row.can_prompt, lifecycle: "running" };
        !composer::status::can_send(Some(gate))
    }

    /// How full the open session's window is, once the harness has reported a call (`context` of the snapshot).
    pub fn context(&self) -> Option<&fleet::context::ContextUsage> {
        self.stream.as_ref().and_then(|st| st.context.as_ref()).or(self.ring.mock.as_ref())
    }

    /// Interrupt is live (row 2.4): while a turn runs or the session waits, and no abort is on its way.
    pub fn can_interrupt(&self) -> bool {
        let aborting = self.aborting.is_some() && self.aborting == self.draft_owner();
        !self.composer_disabled() && composer::status::can_interrupt(self.composer_status(), aborting)
    }

    /// Report this: the problem-report dialog is not in the native app yet (component 17 of the port).
    pub fn report_turn_failure(&mut self, _summary: &str, tx: &mut Tx) {
        self.toast("The problem report isn't in the native app yet.".into(), None, 4.0, tx);
    }

    /// A scene: the open session's composer holds `text` (put in the drafts, which the first frame reads back).
    pub fn show_draft(&mut self, text: &str) {
        if let Some(owner) = self.draft_owner() {
            self.drafts.write(&composer::drafts::session_draft_key(&owner), text, 0.0);
        }
    }

    /// Scenes for the pictures waiting in the composer (piece N): invented pictures, handed over as if a thread had read them.
    fn show_images_held(&mut self, state: &str) {
        self.set_open((0, 2));
        let owner = self.draft_owner().unwrap_or_default();
        let wide = [("checkout.png", mock::images::PAGE), ("logo.png", &include_bytes!("../assets/weave_logo.png")[..])];
        let names: &[(&str, &[u8])] = if state == "images" || state == "image-lightbox" { &wide[..1] } else { &wide };
        let long = ("a-screenshot-with-a-very-long-name.png", mock::images::PAGE);
        for (i, (name, bytes)) in names.iter().chain(if state == "images-many" { Some(&long) } else { None }).enumerate() {
            let image = composer::attach::HeldImage {
                id: format!("scene{i}"),
                mime: "image/png".into(),
                filename: (*name).into(),
                data: std::sync::Arc::from(composer::attach::encode_base64(bytes)),
            };
            self.supply_image(&image.preview_key(), bytes);
            self.attach.add(&owner, image);
        }
        match state {
            "image-error" => {
                self.show_draft("What is wrong with this?");
                self.attach.set_error("notes.txt isn't a PNG, JPEG, GIF or WebP picture.", 0.0);
            }
            "image-queue" => {
                self.set_open((0, 0));
                self.show_draft("Also keep the 200 MB limit.");
                self.composer_error = Some(composer::attach::QUEUE_REFUSAL.into());
            }
            "image-drag" => self.dragging = true,
            "image-lightbox" => self.open_lightbox("attach-scene0", "checkout.png", "attachment-thumb-scene0"),
            _ => self.show_draft("What is wrong with this page?"),
        }
    }

    /// Scenes for the composer's states (docs/parity/05-composer.md, piece B).
    pub fn show_composer(&mut self, state: &str) {
        match state {
            "idle" => self.set_open((0, 2)),
            "typed" => {
                self.set_open((0, 2));
                self.show_draft("Add a test for the rename step too.");
            }
            "busy" => {
                self.set_open((0, 0));
                self.show_draft("Also keep the 200 MB limit.");
            }
            "disabled" => {
                self.set_open((0, 2));
                self.projects[0].sessions[2].row.archived = true;
            }
            // A working session with two messages waiting and a third typed: on a harness that steers (Enter queues,
            // Ctrl+Enter steers), on OpenCode 2 (Enter steers) and on one that can't steer.
            "queue" => self.show_queue("opencode", true, false),
            "queue-opencode2" => self.show_queue("opencode2", true, true),
            "queue-no-steer" => self.show_queue("claude-code", false, false),
            "error" => {
                self.set_open((0, 2));
                self.show_draft("Run the cache tests again.");
                self.composer_error = Some("HTTP 500".into());
            }
            "files" | "file-error" | "uploading" | "paste-offer" | "pasted-file" | "terminal-lines" => self.show_files(state),
            "images" | "images-many" | "image-error" | "image-queue" | "image-drag" | "image-lightbox" => self.show_images_held(state),
            "long" => {
                self.set_open((0, 2));
                let lines: Vec<String> = (1..=12).map(|n| format!("Step {n}: read the file and say what it does.")).collect();
                self.show_draft(&lines.join("\n"));
            }
            "side" => {
                self.set_open((0, 2));
                self.side_open = true;
            }
            // The side mode with a question typed, and shell mode on a harness that runs commands (row 9.1).
            "side-typed" => {
                self.show_composer("side");
                self.show_draft("Which file sets the cache limit?");
            }
            "shell" => {
                self.show_shell_harness();
                self.show_draft("!ls src");
            }
            // The last five messages sent, the newest highlighted (row 8.3).
            "history" => {
                self.set_open((0, 2));
                let owner = self.draft_owner().unwrap_or_default();
                for text in [
                    "Add a test for the rename step too.",
                    "Run the cache tests again.",
                    "Summarise what changed in a short list.",
                    "Why does the pager skip the last page when the count divides evenly?",
                    "Keep the 200 MB limit.",
                ] {
                    self.drafts.push_history(&owner, text, 0.0);
                }
                self.drafts.history_mut(&owner).open();
            }
            // The effort toggle (a model with levels, the third picked) and the pickers' menus.
            "effort" => {
                self.set_open((0, 2));
                let owner = self.draft_owner().unwrap_or_default();
                let model = composer::choice::create_model_selection_key("anthropic", "opus-5-5");
                self.drafts.set_choice(&owner, composer::drafts::Choice { model, effort: "high".into(), ..Default::default() });
            }
            "agent-menu" => {
                self.set_open((0, 2));
                self.open_selector("agent");
            }
            "model-menu" => {
                self.set_open((0, 2));
                self.open_selector("model");
            }
            // Typed text keeps the rows that contain it; the highlight moves to the first match.
            "model-filtered" => {
                self.set_open((0, 2));
                self.open_selector("model");
                self.ui.sel.filter = rune::TextEdit::new("o");
                self.keep_selector();
            }
            // Nothing matches: Default stays (it always does), so the list never goes empty.
            "model-nomatch" => {
                self.set_open((0, 2));
                self.open_selector("model");
                self.ui.sel.filter = rune::TextEdit::new("zzz");
                self.keep_selector();
            }
            // A favourite on top of the list, and the pointer on a row that isn't starred.
            "model-starred" => {
                self.set_open((0, 2));
                let key = composer::groups::model_picker_key("opencode", "anthropic", "opus-5-5");
                let picker = composer::groups::ModelPicker { favourites: vec![key], ..Default::default() };
                self.pickers.prefs.set(composer::groups::PREFERENCE_KEY, &picker.to_json());
                self.open_selector("model");
                self.ui.sel.active = 3;
            }
            "models-long" => {
                self.set_open((0, 2));
                self.pickers.add_mock_models(15);
                self.open_selector("model");
            }
            // Usage bars on the provider headings: 60% (quiet), 97% (dimmed, with its reset time), used up.
            "models-usage" => {
                self.set_open((0, 2));
                self.pickers.add_mock_provider_models(("openai", "OpenAI"), 3);
                self.pickers.add_mock_provider_models(("github-copilot", "GitHub Copilot"), 2);
                let now = 20_000 * 86_400_000 + (12 * 3600 - conv::time::local_offset_secs()) * 1000;
                self.now_ms = Some(now);
                self.pickers.usage.limits = mock::usage_limits(now);
                self.open_selector("model");
            }
            _ => {}
        }
    }

    /// A session whose harness runs shell commands (`supportsShellCommands`).
    fn show_shell_harness(&mut self) {
        self.set_open((0, 2));
        self.projects[0].sessions[2].row.harness_type = Some("opencode".into());
        self.pickers.harnesses = vec![composer::status::HarnessInfo {
            kind: "opencode".into(),
            supports_shell_commands: true,
            supports_side_conversations: true,
            ..Default::default()
        }];
    }

    /// A list with a row for every status, over a fixed clock (docs/parity/06-session-list.md, rows 3.20-3.48).
    fn show_row_statuses(&mut self, dark: bool) {
        self.dark = Some(dark);
        self.now_ms = Some(mock::rows::NOW);
        self.projects = vec![mock::rows::statuses()];
        self.set_open((0, 5));
    }

    /// A list of rows with a running chip, progress and a pull request badge (piece D, rows 3.49-3.54).
    fn show_row_chips(&mut self, dark: bool) {
        self.dark = Some(dark);
        self.now_ms = Some(mock::rows::NOW);
        self.projects = vec![mock::rows::chips()];
        self.set_open((0, 4));
    }

    /// The session list's pull request badges drawn from smart links over the wire's shape, not from a badge written on the
    /// row (`mock::links`; piece F of component 8).
    fn show_pr_badges_from_links(&mut self, dark: bool) {
        self.show_row_chips(dark);
        let wires = mock::links::chips_links(&self.projects[0]);
        for session in &mut self.projects[0].sessions {
            session.row.pr = None;
        }
        self.smart_links.header_links_loaded(&wires);
    }

    /// The queue scenes: the working session, its harness and what it waits for.
    fn show_queue(&mut self, harness: &str, steers: bool, by_default: bool) {
        use composer::status::{HarnessInfo, SteerDelivery};
        self.set_open((0, 0));
        self.projects[0].sessions[0].row.harness_type = Some(harness.into());
        self.pickers.harnesses = vec![HarnessInfo {
            kind: harness.into(),
            supports_steering: steers,
            steers_by_default: by_default,
            steer_delivery: steers.then_some(SteerDelivery::NextStep),
            ..Default::default()
        }];
        let owner = self.draft_owner().unwrap_or_default();
        let item = |id: &str, text: &str, kind, from_mod: Option<&str>| fleet::queue::Item {
            id: id.into(),
            text: text.into(),
            kind,
            from_mod: from_mod.map(str::to_string),
        };
        use fleet::queue::ItemKind::{Command, Prompt};
        self.queue.replace(
            &owner,
            vec![
                item("a", "Then run the cache tests again.", Prompt, None),
                item("b", "/review src/cache", Command, None),
                item("c", "Summarise what changed in a short list.", Prompt, Some("digest")),
            ],
        );
        self.show_draft("Also keep the 200 MB limit.");
    }

    /// The drafts file was read: its text joins what is in memory, and the text area shows its session's if empty.
    pub fn adopt_drafts(&mut self, dir: std::path::PathBuf, stored: composer::drafts::Stored) {
        self.drafts.set_dir(Some(dir));
        self.drafts.merge(stored);
        if let Some(owner) = self.draft_of.clone()
            && let Some(picks) = self.drafts.picks_of(&owner).cloned()
        {
            self.auto.seed_picks(&owner, picks);
        }
        if let Some(owner) = self.draft_of.clone()
            && self.draft.text.is_empty()
        {
            self.draft = TextEdit::new(self.drafts.text_of(&owner));
        }
    }

    /// Keeps a draft per session (`docs/parity/05-composer.md`, piece A; Fleet's `useDraftState`): when another
    /// session is open the text area's text is put away under the one it was and the new one's comes back; what
    /// is typed is noted, and written to the file a moment after the last change, on a thread.
    fn keep_drafts(&mut self, now: f64, tx: &mut Tx) {
        let Some(owner) = self.draft_owner() else { return };
        if self.draft_of.as_deref() != Some(owner.as_str()) {
            let had_old = self.draft_of.is_some();
            if let Some(old) = self.draft_of.take() {
                self.drafts.write(&composer::drafts::session_draft_key(&old), &self.draft.text, now);
            }
            self.draft = TextEdit::new(self.drafts.text_of(&owner));
            self.draft_of = Some(owner.clone());
            if let Some(picks) = self.drafts.picks_of(&owner).cloned() {
                self.auto.seed_picks(&owner, picks);
            }
            // The error box, the optimistic busy and an abort on its way belong to the composer of one session
            // (not cleared on the first look, so a scene can set them).
            if had_old {
                self.composer_error = None;
                self.optimistic = None;
                self.aborting = None;
            }
        } else if self.drafts.text_of(&owner) != self.draft.text {
            self.drafts.write(&composer::drafts::session_draft_key(&owner), &self.draft.text, now);
        }
        self.keep_side_drafts(&owner, now);
        self.keep_caret_outside_references();
        self.keep_picks(&owner, now);
        if self.drafts.save_due(now) {
            if let Some((dir, json)) = self.drafts.take_save() {
                composer::drafts::spawn_save(dir, json);
            }
        } else if self.drafts.unsaved() {
            tx.wake_after(std::time::Duration::from_secs_f64(composer::drafts::SAVE_AFTER));
        }
    }
}

/// Enter, Ctrl/Cmd+Enter and the Send button (`handleSend`, row 2.10): the draft goes where `route_draft` says.
/// `modifier` is the other choice of Enter: steer where Enter queues, queue where it steers. A turn that runs takes a
/// prompt, a slash command or a `!` command into the queue (or a prompt into the turn, when the harness steers); a command
/// or a shell command runs at once.
pub fn submit(s: &mut State, tx: &mut Tx, modifier: bool) {
    // The files are going up: Send waits for them (`isUploading`).
    if s.composer_disabled() || s.shell_support_pending() || s.uploading {
        return;
    }
    s.offer = None;
    let caps = s.caps();
    let cx = composer::route::DraftContext {
        status: s.composer_status(),
        steer: composer::route::steer_for_key(&caps, modifier),
        caps,
        side_open: s.side_open,
    };
    let mut route = composer::route::route_draft(&s.draft.text, &cx);
    // Pictures, files or terminal lines alone are a prompt (`submit` lets an empty draft through when it has them).
    if route == composer::route::Route::Empty && s.extras() > 0 && !s.side_open {
        let steer = cx.steer && cx.status == composer::status::ComposerStatus::Busy && cx.caps.can_steer;
        route = composer::route::Route::Prompt { queue: cx.status == composer::status::ComposerStatus::Busy && !steer, steer };
    }
    // Files go up first, in order; the send carries on once the note is in the text. A command, a shell command and a side
    // question have no use for them.
    if matches!(route, composer::route::Route::Prompt { .. }) && !s.held_files().is_empty() && s.start_upload(modifier, tx) {
        return;
    }
    // Fleet's queue holds text only: with pictures pending, a prompt that would wait keeps both and says why.
    if matches!(route, composer::route::Route::Prompt { queue: true, .. }) && !s.held_images().is_empty() {
        s.composer_error = Some(composer::attach::QUEUE_REFUSAL.into());
        return;
    }
    match route {
        composer::route::Route::Empty => {}
        // The panel is component 15's: until it is built the draft stays, as the kit's `waiting()` entries do.
        composer::route::Route::Side { question } => s.ask_side_question(tx, question),
        composer::route::Route::Prompt { queue: true, .. } => queue_draft(s, tx, fleet::queue::ItemKind::Prompt, None),
        composer::route::Route::Command { command, args, queue: true } => {
            queue_draft(s, tx, fleet::queue::ItemKind::Command, Some((command, args)))
        }
        // An empty command (`!` and spaces) does nothing (row 9.3).
        composer::route::Route::Shell { command, .. } if command.is_empty() => {}
        composer::route::Route::Shell { queue: true, .. } => queue_draft(s, tx, fleet::queue::ItemKind::Shell, None),
        composer::route::Route::Shell { command, queue: false } => s.run_shell(tx, command),
        // A slash command runs as a command (piece K). Without a server the canned reply stands in, as for a prompt.
        composer::route::Route::Command { command, args, queue: false } if s.link.is_some() && s.open_id().is_some() => {
            s.send_command(tx, command, args);
            tx.focus("composer", false);
        }
        composer::route::Route::Prompt { steer, .. } => {
            send_as(s, tx, steer);
            tx.focus("composer", false);
        }
        _ => {
            send(s, tx);
            tx.focus("composer", false);
        }
    }
}

/// While a turn runs, the draft waits in Fleet's queue (`queueDraft`): it clears at once, and comes back if Fleet
/// refuses it and nothing new was typed. The pick (agent, model, effort) goes with it.
fn queue_draft(s: &mut State, tx: &mut Tx, kind: fleet::queue::ItemKind, command: Option<(String, String)>) {
    let typed = s.draft.text.clone();
    let mut text = typed.trim().to_string();
    let Some(owner) = s.draft_owner() else { return };
    let lines = kind == fleet::queue::ItemKind::Prompt && !s.terminal_lines().is_empty();
    if text.is_empty() && !lines {
        return;
    }
    let now = s.clock;
    if !text.is_empty() {
        s.drafts.push_history(&owner, &text, now);
    }
    // Terminal lines wait in the queue with the text, as blocks in front of it, and leave the draft.
    if lines {
        text = composer::attached::format_terminal_context(s.terminal_lines(), &text);
        s.held.clear_terminals(&owner);
    }
    let mut pick = s.prompt_pick(None);
    if kind == fleet::queue::ItemKind::Prompt {
        s.add_references(&mut pick, &text);
    }
    s.record_recent_model(&pick);
    let options = fleet::queue::Options { kind, command, pick };
    s.draft.clear();
    s.enqueue(&owner, typed, text, options);
    tx.focus("composer", false);
}

/// The composer's Send: the message joins the conversation, and a canned reply follows.
pub fn send(s: &mut State, tx: &mut Tx) {
    send_as(s, tx, false);
}

/// Send, into the running turn when `steer`.
pub fn send_as(s: &mut State, tx: &mut Tx, steer: bool) {
    let typed = s.draft.text.trim().to_string();
    let images = !s.held_images().is_empty();
    if typed.is_empty() && !images && s.terminal_lines().is_empty() {
        return;
    }
    // A session on a machine that isn't answering can't be asked: the draft stays, and the machine is named.
    if let Some(why) = s.machine_refusal() {
        s.composer_error = Some(why);
        return;
    }
    // Terminal lines go in front of what was typed, as fenced blocks (`formatTerminalContext`).
    let text = composer::attached::format_terminal_context(s.terminal_lines(), &typed);
    // Row 8.1: what is sent is remembered for ArrowUp, before it goes anywhere.
    if let Some(owner) = s.draft_owner() {
        let now = s.clock;
        if !typed.is_empty() {
            s.drafts.push_history(&owner, &typed, now);
        }
    }
    send_text(s, tx, text, &typed, steer, images);
    s.draft.clear();
}

/// "Try again" on a failure card: the last prompt goes again, as a new message (`retryPrompt`).
pub fn retry_turn(s: &mut State, tx: &mut Tx) {
    if s.composer_disabled() {
        return;
    }
    if let Some(text) = view::failure::last_prompt(&s.session().messages) {
        send_text(s, tx, text.clone(), &text, false, false);
    }
}

/// Sends `text` to the open session. On a server the message goes to the agent, and the conversation shows it at once,
/// as sent but not yet confirmed; without one, a canned reply follows.
fn send_text(s: &mut State, tx: &mut Tx, text: String, typed: &str, steer: bool, with_images: bool) {
    s.composer_error = None;
    s.optimistic = Some(composer::status::Optimistic::new(s.clock));
    tx.wake_after(std::time::Duration::from_secs_f64(composer::status::Optimistic::GIVE_UP + 0.1));
    if let (Some(_), Some(id)) = (&s.link, s.open_id()) {
        s.send_prompt_with(&id, &text, typed, steer, with_images);
        s.notice = None;
        s.follow_end(tx);
        tx.wake_after(std::time::Duration::from_secs_f64(composer::status::Optimistic::GIVE_UP + 0.1));
        // `poll` turns what is still unconfirmed by then into "retry".
        tx.wake_after(std::time::Duration::from_secs_f64(fleet::prompts::CONFIRMATION_TIMEOUT + 0.1));
        return;
    }
    // Without a server the pictures leave the draft with the words, as they do when a Fleet takes the prompt.
    if let Some(owner) = s.draft_owner() {
        let gone = s.attach.clear(&owner);
        s.forget_previews(&gone);
        s.held.clear_terminals(&owner);
    }
    let (p, i) = s.open_at();
    let now = view::message::now_ms(s);
    let session = &mut s.projects[p].sessions[i];
    let id = format!("u{}", session.messages.len() + 1);
    session.messages.push(Message::user(id, text));
    session.status = Status::Working;
    session.touch(now);
    s.working_since = s.clock;
    s.reply = Some((p, i, s.clock + 2.5));
    s.follow_end(tx);
    tx.wake_after(std::time::Duration::from_millis(2600));
}

/// Esc, and the composer's Interrupt button.
pub fn interrupt(s: &mut State) {
    if !s.can_interrupt() {
        return;
    }
    s.aborting = s.draft_owner();
    s.optimistic = None;
    if let Some((link, id)) = s.open_id().and_then(|id| s.link_for(&id).map(|l| (l, id))) {
        link.abort(&id);
        return;
    }
    let (p, i) = s.open_at();
    let session = &mut s.projects[p].sessions[i];
    if session.status != Status::Idle {
        session.status = Status::Idle;
        end_tools(session);
        s.reply = None;
        s.script = None;
        s.script_next = f64::INFINITY;
    }
}

/// A turn that ends takes its running tool calls with it.
fn end_tools(session: &mut Session) {
    for part in session.messages.iter_mut().flat_map(|m| m.parts.iter_mut()) {
        if let Part::Tool { status, .. } = part
            && *status == ToolStatus::Running
        {
            *status = ToolStatus::Completed;
        }
    }
}

fn poll(s: &mut State, now: f64, tx: &mut Tx) -> bool {
    let composer_changed = s.keep_composer_state(now)
        | s.keep_autocomplete(now, tx)
        | s.keep_attachments(tx)
        | s.keep_new_message(tx)
        | s.keep_new_mentions(now, tx);
    let scrolled = s.keep_scroll(tx);
    let pictures = s.keep_images(tx);
    let renamed = s.keep_rename(tx) | s.keep_row_rename(tx) | s.keep_header(now, tx);
    let found = s.find_poll(tx) | s.keep_questions(tx) | s.keep_allowed_flash(now, tx);
    let exported = s.export_poll(tx) | s.keep_setup_rows(now, tx) | s.keep_context(now, tx) | s.keep_machine_page(now, tx);
    // "Copied" on a message's button ends by itself.
    let copied = match &s.copied {
        Some((_, until)) if now >= *until => {
            s.copied = None;
            true
        }
        Some(_) => {
            tx.wake_after(std::time::Duration::from_millis(100));
            false
        }
        None => false,
    };
    poll_rest(s, now, tx) || composer_changed || copied || scrolled || pictures || found || exported || renamed
}

impl State {
    /// The Allowed chip's flash redraws until it has faded (row 5.2).
    fn keep_allowed_flash(&mut self, now: f64, tx: &mut Tx) -> bool {
        let Some(start) = self.allowed_flash else { return false };
        if now - start >= view::allowed::FLASH_SECS {
            self.allowed_flash = None;
        } else {
            tx.wake_after(std::time::Duration::from_millis(33));
        }
        true
    }

    /// The list re-reads the clock every 30 s so "12m" becomes "13m" (`TICK_INTERVAL_MS`); true when it is time to
    /// redraw the rows. The first call only starts the wait.
    pub(crate) fn keep_row_ages(&mut self, now: f64, tx: &mut Tx) -> bool {
        let every = fleet::row_status::TICK_SECS;
        match self.row_tick {
            Some(at) if now - at < every => false,
            last => {
                self.row_tick = Some(now);
                tx.wake_after(std::time::Duration::from_secs_f64(every));
                last.is_some()
            }
        }
    }

    /// The composer's guesses end with the session's own word: true when one did and the buttons must redraw.
    fn keep_composer_state(&mut self, now: f64) -> bool {
        let busy = self.session().status == Status::Working;
        let mut changed = false;
        if let Some(o) = &mut self.optimistic
            && !o.keep(busy, now)
        {
            self.optimistic = None;
            changed = true;
        }
        if self.aborting.is_some() && self.session().status == Status::Idle {
            self.aborting = None;
            changed = true;
        }
        changed
    }
}

fn poll_rest(s: &mut State, now: f64, tx: &mut Tx) -> bool {
    // Whole seconds only, so the "Working · 18s" label redraws once a second.
    let ticked = now.floor() != s.clock.floor();
    s.clock = now;
    let aged = s.keep_row_ages(now, tx);
    s.keep_drafts(now, tx);
    let archiving = s.keep_archive(now, tx) | s.keep_lineage(now, tx);
    let picked = s.sync_selection(tx);
    if s.prompts.expire(now) {
        s.sync_open();
        return true;
    }
    let plain = match &s.ui.toast {
        Some(t) if now >= t.until => {
            s.ui.toast = None;
            true
        }
        Some(_) => {
            tx.wake_after(std::time::Duration::from_millis(100));
            true
        }
        None => false,
    };
    if archiving || plain || picked {
        return true;
    }
    match s.reply {
        Some((p, i, due)) if now >= due => {
            let session = &mut s.projects[p].sessions[i];
            end_tools(session);
            let id = format!("a{}", session.messages.len() + 1);
            let reply = Part::text(format!("{id}-t"), mock::CANNED_REPLY);
            session.messages.push(Message::assistant(id, vec![reply]));
            session.status = Status::Idle;
            s.reply = None;
            s.follow_end(tx);
            true
        }
        _ => {
            s.tick_script() || (ticked && s.session().status == Status::Working) || s.keep_retry_clock(tx) || s.keep_work_clock(tx) || aged
        }
    }
}

fn on_key(s: &mut State, ev: &KeyEvent, tx: &mut Tx) -> bool {
    if s.find_key(ev, tx) || view::permission::on_key(s, ev, tx) || view::question::on_key(s, ev, tx) {
        return true;
    }
    if ev.is_command('k') {
        ui::palette::toggle(s, tx);
    } else if ev.is_command('b') && ev.mods.shift {
        s.set_content_open(!s.content_open);
    } else if ev.is_command('b') {
        s.set_sidebar_open(!s.sidebar_open);
    } else if ev.is_command('[') {
        s.step(-1, tx);
    } else if ev.is_command(']') {
        s.step(1, tx);
    } else if ev.is_command('n') && !ev.mods.shift {
        // `Cmd+N` on macOS, `Ctrl+N` elsewhere (A2.5): the page for a session in no project in particular.
        s.open_new_session_page(None);
    } else if ev.is_command('l') && ev.mods.shift {
        // Not a Fleet shortcut: a quick way to see both themes in the prototype.
        s.dark = Some(!s.drawn_dark.get());
    } else if ev.key == Key::Escape && s.selection.is_selecting() {
        // `handleSelectionKeydown`: Esc lets the picked rows go, and only that.
        s.selection.clear();
    } else if ev.key == Key::Escape {
        interrupt(s);
    } else {
        return false;
    }
    true
}

fn setup(s: &mut State, waker: rune::Waker) {
    let cache = s.cache.insert(ImageCache::new(waker));
    let logo = cache.load(&include_bytes!("../assets/weave_logo.png")[..]);
    // Decoded before the first frame, so a headless snapshot has the logo in it.
    #[cfg(not(target_arch = "wasm32"))]
    let _ = logo.wait();
    s.logo = Some(logo);
}

