/// The browser build's entry point; the desktop build starts from `main.rs`.
#[cfg_attr(target_arch = "wasm32", wasm_bindgen::prelude::wasm_bindgen(start))]
pub fn start() {
    rune::run(spec());
}

/// What `--version` prints: the build number and commit CI baked in (`FLEET_NATIVE_BUILD`, `FLEET_NATIVE_COMMIT`),
/// or `dev` for a local build. The updater compares the build number with the release's `latest.json`.
pub fn version_line() -> String {
    match (option_env!("FLEET_NATIVE_BUILD"), option_env!("FLEET_NATIVE_COMMIT")) {
        (Some(build), Some(commit)) => format!("fleet-native build {build} ({})", &commit[..commit.len().min(7)]),
        _ => "fleet-native dev".to_string(),
    }
}

/// The desktop entry point: `--server <url>` shows that Fleet; every other argument is Rune's own
/// (`--snap`, `--script`, ...).
pub fn start_desktop() {
    if std::env::args().skip(1).any(|a| a == "--version" || a == "-V") {
        println!("{}", version_line());
        return;
    }
    if std::env::args().skip(1).any(|a| a == "--update-now") {
        std::process::exit(update::update_now(!std::env::args().any(|a| a == "--no-restart")));
    }
    if std::env::args().any(|a| a == "--bench-conversation") {
        return bench::conversation();
    }
    // The token comes out of the arguments before anything else sees them, and is kept in `fleet::auth` only.
    let (token, args) = fleet::auth::split_token(std::env::args().skip(1));
    fleet::auth::set(fleet::auth::explicit_token(token, &|k| std::env::var(k).ok()));
    let (server, rest) = split_args(args.into_iter());
    // `--demo`: the invented data on purpose, for a look by hand. It is Fleet Native's own, not Rune's.
    let demo = rest.iter().any(|a| a == "--demo");
    let rest: Vec<String> = rest.into_iter().filter(|a| a != "--demo").collect();
    // `--server` wins; Finder can't pass arguments, so `FLEET_NATIVE_SERVER` names the address as well.
    let server = fleet::discover::explicit_server(server, &|k| std::env::var(k).ok());
    // Pictures, scripted runs and scenes never go looking for a Fleet: they must come out the same every time.
    let headless =
        rest.iter().any(|a| matches!(a.as_str(), "--snap" | "--script" | "--scene" | "--video" | "--frames" | "--tree" | "--trace"));
    if let Some(url) = &server {
        let _ = SERVER.set(url.clone());
    } else if !headless && !demo {
        LIVE.store(true, std::sync::atomic::Ordering::Relaxed);
    }
    // The server hears whether the window has the keyboard and is on screen (`fleet::presence`).
    let app = App::new(spec())
        .args(rest)
        .on_focus(|s, focused, _| {
            s.each_link(|link| link.window_focus(focused));
        })
        .on_visibility(|s, visible, _| {
            s.each_link(|link| link.window_visible(visible));
        });
    let handle = app.handle();
    // The drafts and the remembered choices (folded groups, the side panels) come back from the app's own data folder, read off the UI thread. A picture or a scripted run
    // only touches the folder when `FLEET_NATIVE_DATA_DIR` names one, so they come out the same every time.
    if (!headless || std::env::var_os("FLEET_NATIVE_DATA_DIR").is_some())
        && let Some(dir) = composer::drafts::app_dir(|k| std::env::var(k).ok())
    {
        let handle = handle.clone();
        std::thread::spawn(move || {
            let stored = composer::drafts::load(&dir);
            let settings = fleet::settings::load(&dir);
            let machines = fleet::machine_cache::load(&dir);
            handle.update(move |s, _| {
                s.adopt_machine_cache(dir.clone(), machines);
                s.adopt_settings(dir.clone(), settings);
                s.adopt_drafts(dir, stored);
            });
        });
    }
    if !headless {
        update::start_checker(&handle);
    }
    if let Some(url) = server {
        connect_to(&handle, url);
    } else if !headless && !demo {
        // No `--server`: look for the Fleet running on this machine, as Fleet's desktop app does
        // (`fleet::instance`), off the UI thread because it reads a file and asks the server.
        let handle = handle.clone();
        // It keeps looking: Fleet's desktop app may still be starting its server, or be started after this window.
        std::thread::spawn(move || {
            let mut told = false;
            let found = fleet::discover::search(
                || fleet::discover::all_places(fleet::discover::Os::current(), &|k| std::env::var(k).ok()),
                fleet::discover::LOOK_AGAIN,
                |looked| {
                    if !std::mem::replace(&mut told, true) {
                        let notice = fleet::discover::not_found(looked);
                        eprintln!("fleet-native: {notice}");
                        handle.update(move |s, _| s.on_no_fleet(notice));
                    }
                },
            );
            eprintln!("fleet-native: found a Fleet at {} ({})", found.url, found.place.describe());
            // A Fleet that asks for a token even on this machine: use this machine's own, from Fleet's file.
            let looked = fleet::discover::all_places(fleet::discover::Os::current(), &|k| std::env::var(k).ok());
            if fleet::local_token::adopt(&found, &looked) == fleet::local_token::Outcome::Adopted {
                eprintln!("fleet-native: using this machine's access token from Fleet's data folder");
            }
            connect_to(&handle, found.url)
        });
    }
    app.run();
}

/// Starts the connection to the Fleet at `url`. Until discovery finds one, the invented data stays so there is a window to look at.
fn connect_to(handle: &rune::AppHandle<State>, url: String) {
    fleet::auth::bind_home(&url);
    let link = Link::start(url, Post::from_handle(handle.clone()));
    handle.update(move |s, _| {
        // Nothing invented shows against a real server: the list and the conversation stay empty until it answers.
        s.projects.clear();
        s.feeds = Default::default();
        s.seed_feeds_from_settings();
        s.notice = None;
        s.searching = false;
        s.no_fleet = false;
        s.link = Some(link);
        s.load_pickers();
        s.load_smart_links();
        s.load_list_work();
    });
}

/// Takes `--server <url>` (or `--server=<url>`) out of the arguments.
pub fn split_args(args: impl Iterator<Item = String>) -> (Option<String>, Vec<String>) {
    let (mut server, mut rest) = (None, Vec::new());
    let mut args = args;
    while let Some(arg) = args.next() {
        if arg == "--server" {
            server = args.next();
        } else if let Some(url) = arg.strip_prefix("--server=") {
            server = Some(url.to_string());
        } else {
            rest.push(arg);
        }
    }
    (server, rest)
}
